import{_ as i,o,c as e,a0 as c}from"./chunks/framework.DhQjJcnt.js";const d=JSON.parse('{"title":"Skill: /background-logic","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/background-logic.md","filePath":"references/skills/background-logic.md"}'),a={name:"references/skills/background-logic.md"};function t(l,n,r,h,s,g){return o(),e("div",null,[...n[0]||(n[0]=[c('<h1 id="skill-background-logic" tabindex="-1">Skill: <code>/background-logic</code> <a class="header-anchor" href="#skill-background-logic" aria-label="Permalink to &quot;Skill: `/background-logic`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>background-logic</code> (Xử lý Background Logic)</p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/background-logic &lt;Mã-FLOW hoặc Tên-Chức-Năng&gt;</code></li><li><em>Ví dụ:</em><ul><li><code>/background-logic FLOW-AUTO-MESSAGE-BOOKING</code></li><li><code>/background-logic &quot;Thêm job tự động gửi Zalo cho booking&quot;</code></li></ul></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Mã quy trình <code>FLOW-*</code> đã có hoặc tên màn hình liên quan.</li><li>Thông tin về tác vụ ngầm: <ul><li>Sự kiện kích hoạt (Trigger): Sau khi bấm Lưu ở màn hình nào, hoặc chạy theo chu kỳ Cron?</li><li>Logic so khớp (Matching logic): So sánh trường dữ liệu nào với điều kiện gì?</li><li>Hành vi của Job: Gửi tin nhắn Zalo/SMS, đồng bộ đối tác ERP, tạo file báo cáo, gửi email?</li><li>Hạ tầng khái quát: Dữ liệu ghi log vào table nào, đẩy file lên S3 bucket nào?</li><li>Chính sách sự cố: Số lần thử lại (Retry Policy) và cơ chế chống gửi trùng lặp (Idempotency).</li></ul></li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Cập nhật đồng bộ vào file <code>FLOW-*.md</code> tương ứng: <ol><li>Thêm <strong>System Story</strong> vào phần User Stories (<code>## 2. Chuỗi User Stories Đa Tầng</code>).</li><li>Bổ sung các quy tắc xử lý ngầm (Idempotency, Retry Policy) và ma trận trạng thái ngầm (<code>## 3. Quy tắc Nghiệp vụ</code>).</li><li>Đặc tả chi tiết chặng xử lý ngầm và kịch bản phục hồi lỗi/thử lại (<code>## 4. Đặc tả Chi tiết Hành trình Từng Chặng</code>).</li><li>Cập nhật bảng đối chiếu Traceability (<code>## 5. Ma trận Đối chiếu</code>).</li><li>Chèn hoặc cập nhật phân đoạn <code>rect rgb(...)</code> (Background Job) trong sơ đồ Mermaid <code>sequenceDiagram</code>.</li></ol></li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Kỹ năng chuyên trách quản lý, kiểm tra, bổ sung và cập nhật các tác vụ xử lý ngầm (Async Jobs, Workers, Event Triggers, Notification Dispatchers).</li><li><strong>Lợi ích cốt lõi:</strong><ul><li>Tách bạch giữa phần Giao diện (Screens UI) và phần Tự động hóa ngầm (Automation).</li><li>Giúp bổ sung hoặc chỉnh sửa các tính năng tự động (như gửi tin nhắn, quét timeout, đồng bộ hệ thống) vào một flow đã có sẵn mà <strong>không làm xáo trộn</strong> cấu trúc màn hình đã chốt với khách hàng.</li><li>Đảm bảo đầy đủ cả câu chuyện nghiệp vụ (<strong>System Story</strong>) lẫn sơ đồ trực quan (<strong>Sequence Diagram</strong>).</li></ul></li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Kết hợp với <code>/business-process</code> và <code>/grill</code>.</li><li>Kết nối tới <code>architecture/03-business-process/</code> nếu cần đào sâu vào kiến trúc kỹ thuật của Worker.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/background-logic</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const p=i(a,[["render",t]]);export{d as __pageData,p as default};
